<?php

declare(strict_types=1);

namespace App\Repository;

use App\Entity\Appartment;
use App\Entity\Enum\RoomCategoryKind;
use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository;
use Doctrine\ORM\NoResultException;
use Doctrine\ORM\QueryBuilder;
use Doctrine\Persistence\ManagerRegistry;

/**
 * AppartmentRepository.
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 *
 * @extends ServiceEntityRepository<Appartment>
 */
class AppartmentRepository extends ServiceEntityRepository
{
    public function __construct(ManagerRegistry $registry)
    {
        parent::__construct($registry, Appartment::class);
    }

    private function createBaseQueryBuilder(): QueryBuilder
    {
        return $this->createQueryBuilder('a')
            ->leftJoin('a.object', 'o')
            ->addSelect('o');
    }

    private function addDefaultSorting(QueryBuilder $qb): QueryBuilder
    {
        return $qb
            ->addOrderBy('o.name', \SortDirection::Ascending)
            ->addOrderBy('LENGTH(a.number)', \SortDirection::Ascending)
            ->addOrderBy('a.number', \SortDirection::Ascending);
    }

    public function findAll(): array
    {
        return $this->addDefaultSorting($this->createBaseQueryBuilder()->andWhere('a.active = true'))
            ->getQuery()
            ->getResult();
    }

    /**
     * Return all rooms, including inactive ones, for room settings.
     *
     * @return list<Appartment>
     */
    public function findAllIncludingInactive(): array
    {
        return $this->addDefaultSorting($this->createBaseQueryBuilder())
            ->getQuery()
            ->getResult();
    }

    /**
     * Load all apartment IDs for configuration resolution in Online Booking.
     *
     * @return int[]
     */
    public function loadAllIds(): array
    {
        $rows = $this->createQueryBuilder('a')
            ->select('a.id')
            ->where('a.active = true')
            ->getQuery()
            ->getArrayResult();

        return array_map(static fn (array $row): int => (int) $row['id'], $rows);
    }

    /**
     * Return only existing apartment IDs from a given selection.
     *
     * @param int[] $ids
     * @return int[]
     */
    public function loadExistingIds(array $ids): array
    {
        if ([] === $ids) {
            return [];
        }

        $rows = $this->createQueryBuilder('a')
            ->select('a.id')
            ->where('a.id IN (:ids)')
            ->andWhere('a.active = true')
            ->setParameter('ids', $ids)
            ->getQuery()
            ->getArrayResult();

        return array_map(static fn (array $row): int => (int) $row['id'], $rows);
    }

    /**
     * Restricts a query to accommodation: rooms without a category or of a category of that kind.
     * Event spaces stay out of occupancy, overnight stays and the statistics built on them.
     */
    public static function restrictToAccommodation(QueryBuilder $qb, string $apartmentAlias): QueryBuilder
    {
        return $qb
            ->leftJoin($apartmentAlias.'.roomCategory', 'accommodationCategory')
            ->andWhere('(accommodationCategory.id IS NULL OR accommodationCategory.kind = :accommodationKind)')
            ->setParameter('accommodationKind', RoomCategoryKind::ACCOMMODATION->value);
    }

    /**
     * Beds of the accommodation; event spaces are left out.
     *
     * @param int|string|null $objectId Subsidiary ID, or 'all' for every subsidiary
     *
     * @return int|string|null Raw SUM of maximum beds; null for no rooms, 0 on NoResultException
     */
    public function loadSumBedsMinForObject($objectId)
    {
        $qb = $this->createQueryBuilder('u')
            ->select('SUM(u.beds_max)');
        if ('all' !== $objectId) {
            $qb->where('u.object = :id')
                ->setParameter('id', $objectId);
        }
        $query = self::restrictToAccommodation($qb, 'u')->getQuery();

        try {
            return $query->getSingleScalarResult();
        } catch (NoResultException $ex) {
            return 0;
        }
    }

    /**
     * @param int|string|null $propertyId Subsidiary ID, or 'all' for every subsidiary
     *
     * @return list<Appartment> Active rooms in the default subsidiary/room order
     */
    public function findAllByProperty($propertyId = 'all'): array
    {
        if ('all' === $propertyId) {
            return $this->findAll();
        }

        return $this->addDefaultSorting(
            $this->createBaseQueryBuilder()
                ->andWhere('a.active = true')
                ->andWhere('a.object = :id')
                ->setParameter('id', $propertyId)
        )
            ->getQuery()
            ->getResult();
    }

    /**
     * Count accommodation rooms for a specific subsidiary or across all; event spaces are left out.
     *
     * @param int|string|null $objectId Subsidiary ID, or 'all' for every subsidiary
     */
    public function loadRoomCountForObject($objectId): int
    {
        $qb = $this->createQueryBuilder('a')
            ->select('COUNT(a.id)');

        if ('all' !== $objectId) {
            $qb->andWhere('a.object = :id')
                ->setParameter('id', $objectId);
        }
        self::restrictToAccommodation($qb, 'a');

        try {
            return (int) $qb->getQuery()->getSingleScalarResult();
        } catch (NoResultException $ex) {
            return 0;
        }
    }

    /**
     * Return rooms limited to the given room and subsidiary IDs with joins needed for public booking.
     *
     * Event spaces are left out until the booking page can book days instead of nights; they
     * can then be released through the room selection of the online booking settings.
     *
     * @param int[] $roomIds
     * @param int[] $subsidiaryIds
     *
     * @return Appartment[]
     */
    public function findForPublicBooking(array $roomIds, array $subsidiaryIds): array
    {
        if ([] === $roomIds || [] === $subsidiaryIds) {
            return [];
        }

        return $this->createQueryBuilder('a')
            ->leftJoin('a.roomCategory', 'rc')
            ->addSelect('rc')
            ->join('a.object', 'o')
            ->addSelect('o')
            ->where('a.id IN (:roomIds)')
            ->andWhere('a.active = true')
            ->andWhere('o.id IN (:subsidiaryIds)')
            ->andWhere('(rc.id IS NULL OR rc.kind = :accommodationKind)')
            ->setParameter('roomIds', $roomIds)
            ->setParameter('subsidiaryIds', $subsidiaryIds)
            ->setParameter('accommodationKind', RoomCategoryKind::ACCOMMODATION->value)
            ->addOrderBy('rc.name', \SortDirection::Ascending)
            ->addOrderBy('LENGTH(a.number)', \SortDirection::Ascending)
            ->addOrderBy('a.number', \SortDirection::Ascending)
            ->getQuery()
            ->getResult();
    }

    /**
     * Load rooms by IDs including category and subsidiary joins used during deterministic assignment.
     *
     * @param int[] $ids
     *
     * @return Appartment[]
     */
    public function findByIdsWithRelations(array $ids): array
    {
        if ([] === $ids) {
            return [];
        }

        return $this->createQueryBuilder('a')
            ->leftJoin('a.roomCategory', 'rc')
            ->addSelect('rc')
            ->join('a.object', 'o')
            ->addSelect('o')
            ->where('a.id IN (:ids)')
            ->andWhere('a.active = true')
            ->setParameter('ids', $ids)
            ->getQuery()
            ->getResult();
    }
}
